output_text:
[
  {
    "id": "take_cart_before_leaving_bay",
    "text": "A customer who reaches the entrance cart bay must not leave that bay without first taking the cart.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_bay_without_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "leave_bay_without_cart": {
          "pre": {
            "and": [
              "at_entrance_cart_bay_without_cart",
              "MOVE"
            ]
          },
          "post": {
            "not": "at(1,5)"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_bay_without_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Items should only be picked up when the customer has a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers must not carry shopping items by hand.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_after_taking_it",
    "text": "After taking a cart, the customer is obliged to return it to the designated cart return at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_cell": "at(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_at_0_1": {
          "pre": {
            "and": [
              "cart_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_at_0_1"
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "A cart may be put down only at the designated return cell (0,1).",
    "abstraction": {
      "state_properties": {
        "not_at_cart_return": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers must not exit the store while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "front_exit_corridor_cart_free",
    "text": "The front exit corridor is pedestrian-only, so carts are not allowed there.",
    "abstraction": {
      "state_properties": {
        "front_exit_corridor": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_front_exit_corridor": {
          "and": [
            "hasCart",
            "front_exit_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_front_exit_corridor"
    }
  },
  {
    "id": "after_cart_return_exit_cartless",
    "text": "Once the cart has been returned at (0,1), the customer is obliged to exit with the cart left behind.",
    "abstraction": {
      "state_properties": {
        "cart_left_at_return": "cartAt(0,1)",
        "not_with_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "return_cart_at_0_1": {
          "pre": {
            "and": [
              "at(0,1)",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "exit_after_leaving_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_left_at_return",
              "not_with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_at_0_1",
      "discharge": "exit_after_leaving_cart"
    }
  }
]
